package com.kun.pixelwords.audio;

import android.content.Context;
import android.content.res.AssetFileDescriptor;
import android.media.AudioAttributes;
import android.media.SoundPool;
import android.util.Log;

import com.kun.pixelwords.data.Settings;

import java.io.IOException;
import java.util.EnumMap;
import java.util.Map;

/** The chiptune sound pack (assets/sfx, generated by tools/gen_sfx.py), played with low latency. */
public final class Sfx {

    public enum Id {
        UI_TAP("ui_tap"), UI_BACK("ui_back"), UI_TOGGLE("ui_toggle"),
        MODAL_OPEN("modal_open"), MODAL_CLOSE("modal_close"),
        LETTER("letter"), BACKTRACK("backtrack"), SHUFFLE("shuffle"),
        WORD_FOUND("word_found"), TILE_POP("tile_pop"), WORD_BONUS("word_bonus"),
        WORD_WRONG("word_wrong"), WORD_ALREADY("word_already"),
        HINT("hint"), COIN("coin"), COUNT_TICK("count_tick"), STAR("star"),
        COUNT_BEEP("count_beep"), COUNT_GO("count_go"), CLOCK_TICK("clock_tick"), CLOCK_URGENT("clock_urgent"),
        LEVEL_COMPLETE("level_complete"), DAILY_COMPLETE("daily_complete"), TIME_UP("time_up"),
        DUEL_WIN("duel_win"), DUEL_LOSE("duel_lose"), STREAK_UP("streak_up"),
        TILE_LAND("tile_land"), LOGO_STING("logo_sting"),
        MEOW("meow"), BUY("buy");

        final String file;

        Id(String file) {
            this.file = file;
        }
    }

    /** Semitones from the sample's C5: a pentatonic run, so any swipe sounds like a melody. */
    private static final int[] SCALE = {-5, -3, 0, 2, 4, 7, 9, 12};

    private static SoundPool pool;
    private static final Map<Id, Integer> ids = new EnumMap<>(Id.class);

    private Sfx() {}

    public static void init(Context context) {
        if (pool != null) return;
        pool = new SoundPool.Builder()
                .setMaxStreams(10)
                .setAudioAttributes(new AudioAttributes.Builder()
                        .setUsage(AudioAttributes.USAGE_GAME)
                        .setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION)
                        .build())
                .build();
        for (Id id : Id.values()) {
            try (AssetFileDescriptor fd = context.getAssets().openFd("sfx/" + id.file + ".wav")) {
                ids.put(id, pool.load(fd, 1));
            } catch (IOException e) {
                Log.w("Sfx", "missing sound " + id.file, e);
            }
        }
    }

    public static void play(Id id) {
        play(id, 1f, 1f);
    }

    public static void play(Id id, float rate) {
        play(id, rate, 1f);
    }

    public static void play(Id id, float rate, float volume) {
        if (pool == null || !Settings.sound()) return;
        Integer sound = ids.get(id);
        if (sound != null) pool.play(sound, volume, volume, 1, 0, Math.max(0.5f, Math.min(2f, rate)));
    }

    /** The {@code index}-th letter of a swipe climbs the scale. */
    public static void letter(int index) {
        int semi = SCALE[Math.max(0, Math.min(SCALE.length - 1, index))];
        play(Id.LETTER, (float) Math.pow(2, semi / 12.0));
    }
}
